insert into public.insta_posts (post_date, track, status, title, headline, caption, hashtags, image_urls, source_id, source_url, source_name, topic, facts, script, gate_report, mode, version) values ('2026-10-19', 'admissions', 'ready', '2028 대입 개편 — 정시 축소, 학생부 정성평가 확대', '수능 한 방 역전, 2028부턴 더 좁아진다', '수능 한 방 역전, 2028부터는 점점 어려워져요. 2028학년도 대입은 10명 중 8명을 수시로 뽑고, SKY 정시도 5,105명에서 4,529명으로 줄어요. 정시에서도 학생부를 보는 대학이 늘어나니까, 고1·고2라면 ''진로→과목→세특''을 한 줄로 잇는 연습부터 시작해요. 과목 고를 때 다시 꺼내 보게 저장해 두세요 📌

