insert into public.insta_posts (post_date, track, status, title, headline, caption, hashtags, image_urls, source_id, source_url, source_name, topic, facts, script, gate_report, mode, version) values ('2026-10-26', 'admissions', 'ready', '학과 선호 — 의약 독주 속 반도체·AI·무전공', '인기 학과 판도가 바뀌는 중', '상위권 대학 자연계 톱은 여전히 의약계열 차지예요. 의약계열을 둔 12개대에선 지난 다섯 해 자연계 톱 60자리가 전부 의약이었죠. 그런데 그다음 자리는 달라졌어요. 반도체 계약학과는 2027학년도 수시 경쟁률 28.53:1로 역대 최고였고, 인문 톱이 무전공인 대학은 1곳에서 5곳으로 늘었어요(공동 포함). 어느 쪽이든 기본은 과목 실력! 관심 학과의 권장 과목부터 확인해 두세요 📌

